with lang as (select id from languages where code = 'en')
insert into toeic_tests (language_id, title, questions, exam_type)
select lang.id, 'IELTS-like — Test 2', '{"duration_minutes": 45, "part_a": [{"question": "Complète : They ___ in this house for over twenty years.", "options": ["live", "have lived", "lived", "living"], "correct_index": 1}, {"question": "Complète : If the weather ___ better, we would go hiking.", "options": ["is", "was", "were", "will be"], "correct_index": 2}, {"question": "Complète : The report ___ by the end of the month.", "options": ["will finish", "will be finished", "finishes", "is finish"], "correct_index": 1}, {"question": "Complète : She''s the colleague ___ helped me settle in.", "options": ["who", "whom", "whose", "which"], "correct_index": 0}, {"question": "Complète : ___ the delay, the package arrived in good condition.", "options": ["Although", "Because", "Despite", "So"], "correct_index": 2}, {"question": "Complète : He apologized ___ being late.", "options": ["for", "to", "of", "about"], "correct_index": 0}, {"question": "Complète : The museum ___ closed on Mondays.", "options": ["is", "are", "was", "were"], "correct_index": 0}, {"question": "Complète : I wish I ___ that decision differently.", "options": ["make", "made", "had made", "will make"], "correct_index": 2}, {"question": "Complète : Rarely ___ such a beautiful sunset.", "options": ["I have seen", "have I seen", "I saw", "did I saw"], "correct_index": 1}, {"question": "Complète : The bridge ___ currently under repair.", "options": ["is", "are", "was", "were"], "correct_index": 0}, {"question": "Complète : This neighborhood is ___ than it used to be.", "options": ["safe", "safer", "safest", "more safe"], "correct_index": 1}, {"question": "Complète : She admitted ___ the wrong bus.", "options": ["take", "taking", "to take", "took"], "correct_index": 1}, {"question": "Complète : The children ___ playing outside when it started to rain.", "options": ["was", "were", "is", "are"], "correct_index": 1}, {"question": "Complète : We should have ___ earlier to avoid the traffic.", "options": ["leave", "left", "leaving", "to leave"], "correct_index": 1}, {"question": "Complète : It''s the local bakery ___ everyone recommends.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : The library ___ extended its opening hours.", "options": ["has", "have", "having", "had have"], "correct_index": 0}, {"question": "Complète : He''s not used to ___ in a big city.", "options": ["live", "living", "lived", "to live"], "correct_index": 1}, {"question": "Complète : Neither the manager nor the staff ___ informed.", "options": ["was", "is", "were", "has been"], "correct_index": 2}, {"question": "Complète : The festival ___ postponed until next spring.", "options": ["was", "were", "is", "has"], "correct_index": 0}, {"question": "Complète : What impressed visitors most ___ the friendliness of locals.", "options": ["was", "were", "have been", "being"], "correct_index": 0}, {"question": "Complète : She must ___ left her umbrella at the café.", "options": ["has", "have", "had", "having"], "correct_index": 1}, {"question": "Complète : The community project ___ many volunteers over the years.", "options": ["attract", "attracts", "has attracted", "attracting"], "correct_index": 2}, {"question": "Complète : Despite ___ tired, she finished the marathon.", "options": ["be", "being", "been", "to be"], "correct_index": 1}, {"question": "Complète : The shop assistant recommended ___ the blue jacket.", "options": ["buy", "to buy", "buying", "bought"], "correct_index": 2}, {"question": "Complète : This is the park ___ we used to play as children.", "options": ["which", "where", "who", "whose"], "correct_index": 1}, {"question": "Complète : The council ___ a new recycling scheme next month.", "options": ["launches", "is launching", "launch", "launched to"], "correct_index": 1}, {"question": "Complète : I''d rather we ___ a table in advance.", "options": ["book", "booked", "will book", "booking"], "correct_index": 0}, {"question": "Complète : The population of the town ___ doubled in ten years.", "options": ["has", "have", "having", "had have"], "correct_index": 0}, {"question": "Complète : It was the friendly staff ___ made our stay memorable.", "options": ["that", "who is", "which", "what"], "correct_index": 0}, {"question": "Complète : The road ___ closed for maintenance next week.", "options": ["will be", "is being", "has been", "would"], "correct_index": 0}], "part_b": [{"title": "Article général (voyage)", "passage": "Budget airlines have made international travel more accessible than ever, but passengers often face additional fees for luggage, seat selection, and even printing boarding passes. Experts advise travelers to read the terms carefully before booking to avoid unexpected costs.", "questions": [{"question": "What have budget airlines made more accessible?", "options": ["Local trains", "International travel", "Luxury cruises", "Business class flights"], "correct_index": 1}, {"question": "What additional fees are mentioned?", "options": ["Only meals", "Luggage, seat selection, boarding passes", "Only insurance", "Only fuel surcharges"], "correct_index": 1}, {"question": "What do experts advise?", "options": ["Avoid budget airlines entirely", "Read the terms carefully before booking", "Always pay for extras", "Book only in person"], "correct_index": 1}, {"question": "What can travelers avoid by reading terms carefully?", "options": ["Long flights", "Unexpected costs", "Jet lag", "Cancelled flights"], "correct_index": 1}, {"question": "What is the overall tone of the passage?", "options": ["Purely negative about budget airlines", "Informative, noting a caution", "An advertisement", "A complaint letter"], "correct_index": 1}, {"question": "What is the main topic?", "options": ["Airport security", "Hidden costs of budget airlines", "Airline food quality", "Flight delays"], "correct_index": 1}]}, {"title": "Extrait académique (éducation)", "passage": "Studies suggest that students who take short breaks during study sessions retain information better than those who study for long, uninterrupted periods. This method, sometimes called spaced learning, allows the brain time to process and consolidate new material.", "questions": [{"question": "What do studies suggest about short breaks?", "options": ["They reduce retention", "Students retain information better with breaks", "They have no effect", "They only help younger students"], "correct_index": 1}, {"question": "What is this method sometimes called?", "options": ["Cramming", "Spaced learning", "Passive learning", "Group study"], "correct_index": 1}, {"question": "What does the break allow the brain to do?", "options": ["Rest completely", "Process and consolidate new material", "Forget information", "Avoid studying"], "correct_index": 1}, {"question": "What is compared to short breaks in the passage?", "options": ["Group study", "Long, uninterrupted study periods", "No studying at all", "Online courses"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["A study technique", "A history lesson", "A biology experiment", "A grammar rule"], "correct_index": 0}, {"question": "Who is this passage most relevant to?", "options": ["Chefs", "Students", "Athletes", "Musicians"], "correct_index": 1}]}, {"title": "Avis client (produit)", "passage": "I bought this blender two months ago and have been very happy with it. It''s powerful enough to crush ice easily and cleaning it is simple thanks to the removable parts. The only issue is that it''s quite loud, which can be annoying early in the morning.", "questions": [{"question": "How long has the reviewer had the blender?", "options": ["Two weeks", "Two months", "Two years", "Not mentioned"], "correct_index": 1}, {"question": "What can the blender do easily?", "options": ["Bake bread", "Crush ice", "Make coffee", "Toast bread"], "correct_index": 1}, {"question": "Why is cleaning simple?", "options": ["It cleans itself", "Removable parts", "It doesn''t need cleaning", "A special detergent is included"], "correct_index": 1}, {"question": "What is the main complaint?", "options": ["It''s too weak", "It''s quite loud", "It''s too expensive", "It breaks easily"], "correct_index": 1}, {"question": "When is the noise most annoying?", "options": ["At night", "Early in the morning", "During the day", "Not mentioned"], "correct_index": 1}, {"question": "Overall, how does the reviewer feel about the product?", "options": ["Very unhappy", "Very happy, with one minor issue", "Neutral", "Regretful about buying it"], "correct_index": 1}]}, {"title": "Instructions (bibliothèque)", "passage": "To borrow a book: 1. Bring your library card to the front desk. 2. Select up to five books. 3. Hand the books and your card to the librarian for scanning. 4. Books can be kept for three weeks. 5. Renewals can be done online or by phone before the due date.", "questions": [{"question": "What is needed to borrow a book?", "options": ["A passport", "A library card", "A deposit", "An ID and payment"], "correct_index": 1}, {"question": "How many books can be selected?", "options": ["Up to three", "Up to five", "Up to ten", "Unlimited"], "correct_index": 1}, {"question": "Who scans the books?", "options": ["The customer", "The librarian", "A machine only", "No scanning needed"], "correct_index": 1}, {"question": "How long can books be kept?", "options": ["One week", "Two weeks", "Three weeks", "One month"], "correct_index": 2}, {"question": "How can renewals be done?", "options": ["Only in person", "Online or by phone", "By mail only", "Not possible"], "correct_index": 1}, {"question": "When should renewals be done?", "options": ["After the due date", "Before the due date", "Anytime, no deadline", "Only on Mondays"], "correct_index": 1}]}, {"title": "Article général (alimentation)", "passage": "Farmers'' markets have grown in popularity as consumers seek fresher produce and want to support local businesses. While prices can sometimes be higher than in supermarkets, many shoppers feel the quality and the opportunity to meet the producers make the extra cost worthwhile.", "questions": [{"question": "Why have farmers'' markets grown in popularity?", "options": ["Lower prices always", "Consumers want fresher produce and to support local businesses", "Government mandates", "Supermarket closures"], "correct_index": 1}, {"question": "How do prices compare to supermarkets?", "options": ["Always lower", "Sometimes higher", "Exactly the same", "Not mentioned"], "correct_index": 1}, {"question": "What do many shoppers feel makes the cost worthwhile?", "options": ["Free samples", "Quality and meeting producers", "Faster shopping", "Better parking"], "correct_index": 1}, {"question": "What can shoppers do at farmers'' markets that they can''t at supermarkets?", "options": ["Pay with any currency", "Meet the producers", "Buy in bulk cheaply", "Get home delivery"], "correct_index": 1}, {"question": "What is the overall tone of the passage?", "options": ["Critical of farmers'' markets", "Generally positive", "Neutral and purely factual", "Sarcastic"], "correct_index": 1}, {"question": "What is the main topic?", "options": ["Supermarket chains", "The appeal of farmers'' markets", "Organic certification", "Food safety regulations"], "correct_index": 1}]}]}'::jsonb, 'ielts'
from lang;

